import{_ as o,o as t,c as d,a0 as s}from"./chunks/framework.CNXp-E7Q.js";const h=JSON.parse('{"title":"Dogfood: real GitHub Actions workflows through runner.kind = \\"gha\\"","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/gha-dogfood.md","filePath":"explanation/gha-dogfood.md"}'),c={name:"explanation/gha-dogfood.md"};function r(a,e,n,i,l,u){return t(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="dogfood-real-github-actions-workflows-through-runner-kind-gha" tabindex="-1">Dogfood: real GitHub Actions workflows through <code>runner.kind = &quot;gha&quot;</code> <a class="header-anchor" href="#dogfood-real-github-actions-workflows-through-runner-kind-gha" aria-label="Permalink to &quot;Dogfood: real GitHub Actions workflows through `runner.kind = &quot;gha&quot;`&quot;">​</a></h1><p>Parity report for the <code>gha</code> dialect (org-ledger T-003). Method: real <code>.github/workflows/ci.yml</code> files from public Rust repos — the 9aia org repos themselves carry <strong>no</strong> GitHub workflows (CI is hooks + myco/sturn, not GHA), so &quot;real&quot; means upstream public repos — dropped into a scratch git repo and run through <code>bupha run</code> with <code>runner.kind = &quot;gha&quot;</code>. Unsupported constructs were then peeled iteratively (each <code>spawn failed:</code> error fixed, re-run) until each workflow planned <strong>and executed</strong>, recording every error along the way.</p><p>Workflows tested (fetched 2026-11, upstream <code>main</code>/<code>master</code>):</p><table tabindex="0"><thead><tr><th>repo</th><th>file</th><th>jobs</th><th>verdict</th></tr></thead><tbody><tr><td>dtolnay/anyhow</td><td><code>ci.yml</code> (146 lines)</td><td>9</td><td>hard error at spawn; plans+executes after peeling ~35 unsupported constructs</td></tr><tr><td>serde-rs/serde</td><td><code>ci.yml</code> (179 lines)</td><td>10</td><td>hard error at spawn; plans+executes after peeling ~40 unsupported constructs</td></tr><tr><td>BurntSushi/ripgrep</td><td><code>ci.yml</code> (291 lines)</td><td>6</td><td>hard error at spawn; plans+executes after peeling ~20 unsupported constructs</td></tr><tr><td>synthetic subset port</td><td>—</td><td>3</td><td><strong>full pass</strong> — every supported feature exercised green</td></tr></tbody></table><h2 id="first-error-results-unmodified-workflows" tabindex="-1">First-error results (unmodified workflows) <a class="header-anchor" href="#first-error-results-unmodified-workflows" aria-label="Permalink to &quot;First-error results (unmodified workflows)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>workflow</th><th>first <code>spawn failed:</code> error</th></tr></thead><tbody><tr><td>anyhow <code>ci.yml</code></td><td><code>gha: ci.yml.jobs.pre_ci: unsupported key &#39;uses&#39;</code> — job-level reusable-workflow call (<code>uses: dtolnay/.github/.github/workflows/pre_ci.yml@master</code>, line 17)</td></tr><tr><td>serde <code>ci.yml</code></td><td><code>gha: ci.yml.jobs.test: unsupported key &#39;timeout-minutes&#39;</code> (line 19)</td></tr><tr><td>ripgrep <code>ci.yml</code></td><td><code>gha: ci.yml.jobs.test.env.TARGET_FLAGS: expected a scalar, got null</code> — <strong>bug, fixed</strong> (see below); next error is <code>jobs.test.strategy: unsupported key &#39;fail-fast&#39;</code> (line 51)</td></tr></tbody></table><p>Parse is all-or-nothing per file and stops at the first error — the tables below are the <em>complete</em> inventory obtained by peeling.</p><h2 id="unsupported-syntax-inventory-hit-during-peeling" tabindex="-1">Unsupported-syntax inventory hit during peeling <a class="header-anchor" href="#unsupported-syntax-inventory-hit-during-peeling" aria-label="Permalink to &quot;Unsupported-syntax inventory hit during peeling&quot;">​</a></h2><p>Every real workflow hit the same wall, in roughly this order:</p><table tabindex="0"><thead><tr><th>construct</th><th>where it appears</th><th>gha verdict</th></tr></thead><tbody><tr><td>job-level <code>uses:</code> (reusable workflows)</td><td>anyhow <code>pre_ci</code> (L17)</td><td>hard error <code>unsupported key &#39;uses&#39;</code></td></tr><tr><td>job <code>if:</code></td><td>anyhow L22,54,73,85,98,114,126,140; serde L143,157,173; ripgrep step-level mostly</td><td>hard error <code>unsupported key &#39;if&#39;</code></td></tr><tr><td><code>timeout-minutes</code></td><td>every job in anyhow/serde</td><td>hard error <code>unsupported key &#39;timeout-minutes&#39;</code></td></tr><tr><td><code>strategy.fail-fast</code></td><td>anyhow L25,57; serde L44,61,85; ripgrep L51</td><td>hard error <code>unsupported key &#39;fail-fast&#39;</code></td></tr><tr><td>step <code>if:</code></td><td>anyhow L37,40,45; serde L75,79; ripgrep L123,131,143,159,185,193,201,240,258,273,281,293</td><td>hard error <code>unsupported key &#39;if&#39;</code></td></tr><tr><td>step <code>continue-on-error</code></td><td>anyhow L49; serde L29</td><td>hard error <code>unsupported key &#39;continue-on-error&#39;</code></td></tr><tr><td><code>uses:</code> ≠ <code>actions/checkout</code></td><td><code>dtolnay/rust-toolchain</code> (everywhere), <code>dtolnay/install</code>, <code>actions/upload-artifact</code>, <code>docker/setup-docker-action</code>, <code>actions/cache</code>, <code>actions/setup-node</code>, <code>docker://pandoc/…</code></td><td>hard error <code>unsupported &#39;uses: …&#39;</code> — <em><code>dtolnay/rust-toolchain</code> and the artifact actions have since landed; <code>actions/setup-*</code>/<code>actions/cache</code>/<code>docker://</code>/local paths still error</em></td></tr><tr><td><code>strategy.matrix.include</code></td><td>ripgrep L53–117, mdBook main.yml</td><td><code>expected a scalar, got mapping</code></td></tr><tr><td>complex <code>${{ }}</code> expressions</td><td>serde L58 job name (<code>matrix.os == &#39;windows&#39; &amp;&amp; … || &#39;&#39;</code>), ripgrep <code>startsWith(...)</code>, <code>hashFiles(...)</code>, <code>steps.*.outputs.*</code></td><td>hard error <code>unsupported expression</code> — <em><code>steps.*.outputs.*</code>/<code>needs.*.outputs.*</code> since wired (T-069); the rest still error</em></td></tr><tr><td><code>env:</code> null values</td><td>ripgrep L40–42 (<code>TARGET_FLAGS:</code> empty)</td><td><strong>was a bug — fixed</strong> (null now coerces to <code>&quot;&quot;</code>)</td></tr><tr><td>step <code>with:</code> on any <code>uses:</code></td><td>ripgrep L133–135, L249–257</td><td><strong>was a bug — fixed</strong> (<code>with</code> was missing from the step key allowlist; <code>actions/checkout</code> <code>with:</code> inputs now accepted, <code>with.path</code> still errors, <code>with</code> on <code>run:</code> errors)</td></tr><tr><td>job <code>name:</code> <code>${{ }}</code></td><td>serde L41,58,82; anyhow L20,53</td><td><strong>was a bug — fixed</strong> (names are now interpolated; unsupported expressions in names now error loudly instead of passing through verbatim)</td></tr></tbody></table><p>Triggers <code>pull_request</code>, <code>workflow_dispatch</code>, <code>schedule</code>, <code>merge_group</code> are silently ignored — only <code>on.push</code> selects. A workflow with <em>no</em> <code>push</code> trigger parses fine and simply never matches (<code>no on.push workflow matched</code> → vacuous success).</p><h2 id="execution-parity-peeled-workflows" tabindex="-1">Execution parity (peeled workflows) <a class="header-anchor" href="#execution-parity-peeled-workflows" aria-label="Permalink to &quot;Execution parity (peeled workflows)&quot;">​</a></h2><p>Once peeled, all three workflows <strong>plan and execute</strong>: jobs run sequentially in <code>needs</code> topo-order, matrix combos fan out in parallel (private per-leg worktrees), <code>actions/checkout</code> verifies HEAD, step <code>env</code>/<code>working-directory</code>/<code>shell</code> are honored, and failing <code>run</code> steps fail their job while independent jobs continue — matching GHA&#39;s aggregate-status shape. In the scratch repos the cargo/npm steps fail fast (no real project/toolchain), so the aggregate exit is 1 — the <em>machinery</em> is what was verified.</p><p>A purpose-built subset workflow (matrix 2×2, <code>needs</code> chain, workflow/job/step <code>env</code> with <code>${{ env.* }}</code>/<code>${{ matrix.* }}</code>/ <code>${{ github.* }}</code>, <code>defaults.run.working-directory</code> + <code>shell</code>, step <code>working-directory</code> override, <code>shell: sh</code>, <code>actions/checkout</code> with <code>with:</code>, <code>branches</code> + <code>paths-ignore</code> filters) passes <strong>fully green</strong>, including correct skip of a <code>needs</code>-dependent job when a matrix leg fails.</p><h2 id="semantic-gaps-vs-github-actions" tabindex="-1">Semantic gaps vs GitHub Actions <a class="header-anchor" href="#semantic-gaps-vs-github-actions" aria-label="Permalink to &quot;Semantic gaps vs GitHub Actions&quot;">​</a></h2><blockquote><p><strong>Update (T-048).</strong> Several gaps below closed since this report: <code>if:</code> (job+step) now parses a real expression subset — literals, <code>==</code>/<code>!=</code>/<code>&amp;&amp;</code>/<code>||</code>/<code>!</code>/parens, <code>contains</code>/<code>startsWith</code>/<code>endsWith</code>, <code>success()</code>/<code>failure()</code>/<code>cancelled()</code>/<code>always()</code>, plus <code>needs.*.result</code>/<code>steps.*.conclusion</code> — with the implicit <code>success() &amp;&amp;</code> wrap; <code>timeout-minutes</code> is enforced (GNU <code>timeout</code> per step, process-group watchdog per job); <code>strategy.fail-fast</code> cancels remaining matrix legs and <code>max-parallel</code> throttles parallel legs (each leg gets a private <code>git worktree</code>; <code>1</code> pins the sequential path); <code>dtolnay/rust-toolchain</code> lowers to rustup calls; <code>paths</code> filters now infer the push&#39;s <code>before</code> sha from remote-tracking refs/reflogs/merge-base instead of diffing only <code>HEAD^..HEAD</code>. Each expanded job that reaches a verdict (every workflow job, every matrix leg) now also posts its own commit status under <code>&lt;context&gt;/&lt;workflow&gt;/&lt;job id&gt;[/&lt;matrix&gt;]</code> — the aggregate <code>ci/bupha[/&lt;job&gt;]</code> context is unchanged. Parallel matrix landed: legs fan out as process groups in per-leg worktrees, <code>fail-fast</code> kills siblings, and <code>needs.*.outputs.*</code> resolves to the highest-index successful leg — details in the crate README boundaries. <code>actions/upload-artifact</code>/<code>actions/download-artifact</code> also landed since (per-run tar store under the run&#39;s tmp dir — same-run only; see the crate README boundaries), as did <code>actions/setup-*</code> toolchains, <code>actions/cache*</code>, and <strong>composite actions</strong> (<code>uses: ./path</code> + <code>owner/repo[/path]@ref</code> → <code>runs.using: composite</code> <code>action.yml</code>, strict inputs/outputs contract, nested to depth 8). <code>env:</code> on <code>uses:</code> steps now reaches the action. <code>uses: docker://&lt;image&gt;</code> steps and composite <code>timeout-minutes</code> have since landed too (<code>docker run</code> on the host — docker CLI required; the composite timeout is a deadline spanning the inlined steps). <strong>Reusable workflows</strong> (<code>jobs.&lt;id&gt;.uses:</code> → <code>./.github/workflows/*.yml</code> or <code>owner/repo[/path]@&lt;ref&gt;</code>, with <code>on.workflow_call</code> inputs/secrets/outputs, graph merge and <code>secrets: inherit</code>/explicit maps) have since landed as well — details in the crate README. The bullets below are annotated where they changed.</p></blockquote><ul><li><strong><code>$GITHUB_ENV</code> / <code>$GITHUB_OUTPUT</code> / <code>$GITHUB_PATH</code> / <code>$RUNNER_TEMP</code> are unset.</strong> <code>run: echo X=1 &gt;&gt; $GITHUB_ENV</code> fails with <code>ambiguous redirect</code>. This is the biggest functional gap — ripgrep&#39;s cross-install step and anyhow&#39;s nightly RUSTFLAGS steps depend on it. Filed as <strong>T-060</strong> (linked to T-048). <em>(Superseded: these are now wired — see the crate README; the dogfood run predates T-060&#39;s landing.)</em></li><li><strong><code>runs-on</code> is advisory.</strong> <code>windows-latest</code>/<code>macos-latest</code> jobs execute locally on the watcher&#39;s Linux box — serde&#39;s <code>windows</code> job would &quot;pass&quot; having never run Windows. No platform guard or warning today.</li><li><strong>Matrix legs run in private worktrees</strong> (documented): GHA gives each leg a fresh runner checkout; bupha gives each leg a <code>git worktree</code> under the run&#39;s tmp dir, so workspace writes stay per-leg (use job <code>outputs:</code>/artifacts/<code>$BUPHA_WORKDIR</code> to share). ripgrep&#39;s 17-combo <code>include</code> matrix isn&#39;t even expressible (<code>include</code>/<code>exclude</code> unsupported) — cartesian list-form only.</li><li><strong><code>if:</code> supported subset only.</strong> The common constructs now work (see update note), but the full expression language — <code>hashFiles</code>, <code>fromJSON</code>, <code>format</code>, ternary, <code>runner.*</code>, <code>strategy.*</code>, <code>steps.*.outcome</code> — still hard-errors loudly.</li><li><strong>Third-party actions are still mostly the hard wall.</strong><code>actions/setup-*</code>, <code>actions/cache</code>, <code>docker://…</code>, local/composite <code>uses:</code> paths and reusable-workflow <code>uses:</code> all error; <code>dtolnay/rust-toolchain</code> lowers to rustup calls and <code>actions/upload-artifact</code>/<code>actions/download-artifact</code> share a per-run tar store (same-run only — nothing persists across runs). Toolchain setup beyond rustup still needs manual porting. <em>(Superseded: <code>actions/setup-{node,python,go,java, dotnet}</code>, <code>actions/cache*</code>, composite <code>uses:</code> and <code>docker://</code> steps have since landed; JS/docker action <em>definitions</em>, other setup families and reusable-workflow <code>uses:</code> still error.)</em><em>(Superseded again: reusable-workflow <code>uses:</code> has since landed — local <code>./.github/workflows/*.yml</code> and remote <code>owner/repo[/path]@&lt;ref&gt;</code> targets, <code>on.workflow_call</code> contracts, <code>secrets: inherit</code>/explicit maps; see the crate README.)</em></li><li><strong>Expression language grew but stays a subset.</strong> <code>==</code>, <code>!=</code>, <code>&amp;&amp;</code>, <code>||</code>, <code>!</code>, parens, <code>contains</code>/<code>startsWith</code>/<code>endsWith</code>, status functions and the <code>needs.*.result</code>/<code>steps.*.conclusion</code> refs now work in <code>if:</code> and <code>${{ }}</code> (T-048); no ternary, <code>hashFiles</code>, <code>format</code>, <code>fromJSON</code>, or object/array contexts.</li><li><strong>Reusable workflows landed with honest edges</strong> (T-048) — <code>jobs.&lt;id&gt;.uses:</code> now resolves local <code>./.github/workflows/*.yml</code> and remote <code>owner/repo[/path]@&lt;ref&gt;</code> callees, binds <code>with:</code>→<code>inputs.*</code> and <code>secrets:</code>→<code>secrets.*</code>, merges the callee graph under <code>&lt;call&gt;.&lt;job&gt;</code> ids, and exposes <code>on.workflow_call.outputs</code> as <code>needs.&lt;call&gt;.outputs.*</code>. Still unsupported: execution keys on the calling job, callees without <code>on.workflow_call:</code>, <code>secrets.*</code>/<code>jobs.*</code> outside the contract, nesting past depth 8, and <code>secrets:</code> values that aren&#39;t scalars or <code>${{ secrets.X }}</code> forwards.</li><li><strong><code>paths</code> filters infer <code>before</code></strong> (T-048): remote-tracking ref → reflog → local branch → merge-base, falling back to the tip commit. Multi-commit pushes are covered when the repo still has a ref pointing at the push&#39;s base; a <code>before</code> the clone never saw still undercounts (documented boundary).</li><li><strong><code>actions/checkout</code> ignores <code>with.ref</code>/<code>fetch-depth</code></strong> — it is a verification no-op; the worktree is already at the pushed sha. <code>with.path</code> errors.</li><li><strong>Parse-before-filter</strong>: every candidate workflow file is parsed even when its <code>on.push</code> filters wouldn&#39;t match — a broken non-matching workflow still fails the spawn (loud by design, differs from GHA which wouldn&#39;t evaluate it at all).</li><li><strong>Timeouts landed; services/containers/concurrency didn&#39;t</strong> — <code>timeout-minutes</code> is enforced at job (watchdog) and step (<code>timeout</code>) level (T-048); <code>services:</code>, <code>container:</code>, <code>concurrency:</code>, <code>continue-on-error:</code> remain hard errors. Job/step <code>outputs:</code> and the <code>steps.*</code>/<code>needs.*</code> refs are supported since T-069.</li></ul><h2 id="bugs-found-fixed-in-this-dogfood" tabindex="-1">Bugs found &amp; fixed in this dogfood <a class="header-anchor" href="#bugs-found-fixed-in-this-dogfood" aria-label="Permalink to &quot;Bugs found &amp; fixed in this dogfood&quot;">​</a></h2><ol><li><strong><code>env:</code> null values rejected</strong> — <code>KEY:</code> (YAML null) errored <code>expected a scalar, got null</code>; GHA coerces to <code>&quot;&quot;</code>. Fixed in <code>env_map</code> + regression test.</li><li><strong>Step <code>with:</code> unreachable</strong> — <code>with</code> was missing from the step key allowlist <em>and</em> the unsupported list, so <code>actions/checkout</code> <code>with:</code> inputs errored as <code>unknown key &#39;with&#39;</code> before <code>parse_uses</code> could validate them (the <code>with.path</code> check was dead code). <code>with</code> is now allowed on <code>uses</code> steps, rejected on <code>run</code> steps.</li><li><strong>Job <code>name:</code> never interpolated</strong> — <code>${{ matrix.* }}</code> in <code>jobs.&lt;id&gt;.name</code> passed through verbatim into logs. Names are now interpolated like every other field; unsupported expressions in names now fail loudly (consistent with the subset contract).</li></ol><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to &quot;Reproduce&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># scratch repo: git init, commit, drop a real ci.yml into</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .github/workflows/, then:</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bupha</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bupha.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # runner.kind = &quot;gha&quot;</span></span></code></pre></div><p><code>spawn failed: gha: &lt;file&gt;:&lt;path&gt;: &lt;reason&gt;</code> names the exact YAML key — peel iteratively to enumerate the full unsupported surface.</p>',22)])])}const g=o(c,[["render",r]]);export{h as __pageData,g as default};
